from datetime import timedelta

import pytest

from apps.accounts.tests.factories import StudentFactory
from apps.placements.tests.factories import (
    ApprovedPlacementFactory,
    OrganizationFactory,
    PeriodFactory,
    SubmittedPlacementFactory,
)

pytestmark = pytest.mark.django_db

PLACEMENTS = "/api/v1/placements/"


def _payload(period, organization, **overrides):
    data = {
        "period": str(period.id),
        "organization": str(organization.id),
        "role_title": "Intern",
        "department": "IT",
        "task_description": "Build tools.",
        "start_date": str(period.start_date + timedelta(days=7)),
        "end_date": str(period.end_date - timedelta(days=7)),
        "proposed_supervisor_name": "Jane Mentor",
        "proposed_supervisor_email": "jane@acme.example",
    }
    data.update(overrides)
    return data


def test_student_creates_submits_and_tracks_a_placement(auth_client, student):
    period, organization = PeriodFactory(), OrganizationFactory()
    client = auth_client(student)
    created = client.post(PLACEMENTS, _payload(period, organization), format="json")
    assert created.status_code == 201, created.content
    placement_id = created.json()["id"]
    assert created.json()["status"] == "DRAFT"

    submitted = client.post(f"{PLACEMENTS}{placement_id}/submit/")
    assert submitted.status_code == 200, submitted.content
    assert submitted.json()["status"] == "SUBMITTED"

    mine = client.get(f"{PLACEMENTS}me/")
    assert mine.status_code == 200
    assert mine.json()["id"] == placement_id


def test_me_is_404_without_a_placement(auth_client, student):
    assert auth_client(student).get(f"{PLACEMENTS}me/").status_code == 404


def test_other_students_cannot_see_a_placement(auth_client, coordinator):
    placement = SubmittedPlacementFactory()
    url = f"{PLACEMENTS}{placement.id}/"
    assert auth_client(StudentFactory()).get(url).status_code == 404
    assert auth_client(placement.student).get(url).status_code == 200
    assert auth_client(coordinator).get(url).status_code == 200


def test_students_cannot_decide_placements(auth_client):
    placement = SubmittedPlacementFactory()
    client = auth_client(placement.student)
    for action in ("approve", "return", "reject"):
        response = client.post(f"{PLACEMENTS}{placement.id}/{action}/", {}, format="json")
        assert response.status_code == 403, action


def test_coordinator_approves_and_invites_the_proposed_supervisor(
    auth_client, coordinator, academic_supervisor, django_capture_on_commit_callbacks
):
    placement = SubmittedPlacementFactory(proposed_supervisor_email="boss@acme.example")
    with django_capture_on_commit_callbacks(execute=True):
        response = auth_client(coordinator).post(
            f"{PLACEMENTS}{placement.id}/approve/",
            {
                "academic_supervisor": str(academic_supervisor.id),
                "invite_workplace_supervisor": True,
                "remarks": "Welcome aboard",
            },
            format="json",
        )
    assert response.status_code == 200, response.content
    body = response.json()
    assert body["status"] == "APPROVED"
    assert body["workplace_supervisor"]["email"] == "boss@acme.example"
    assert body["academic_supervisor"]["id"] == str(academic_supervisor.id)


def test_approving_twice_is_a_conflict(auth_client, coordinator, academic_supervisor):
    placement = ApprovedPlacementFactory()
    response = auth_client(coordinator).post(
        f"{PLACEMENTS}{placement.id}/approve/",
        {"academic_supervisor": str(academic_supervisor.id), "invite_workplace_supervisor": True},
        format="json",
    )
    assert response.status_code == 409
    assert response.json()["code"] == "invalid_transition"


def test_return_then_resubmit_and_timeline(auth_client, coordinator):
    placement = SubmittedPlacementFactory()
    student_client, coordinator_client = auth_client(placement.student), auth_client(coordinator)
    returned = coordinator_client.post(
        f"{PLACEMENTS}{placement.id}/return/", {"remarks": "Add a phone number."}, format="json"
    )
    assert returned.status_code == 200
    patched = student_client.patch(
        f"{PLACEMENTS}{placement.id}/",
        {"proposed_supervisor_phone": "+254722000000"},
        format="json",
    )
    assert patched.status_code == 200, patched.content
    assert student_client.post(f"{PLACEMENTS}{placement.id}/submit/").status_code == 200

    timeline = student_client.get(f"{PLACEMENTS}{placement.id}/timeline/").json()
    assert [event["status"] for event in timeline] == [
        "DRAFT",
        "SUBMITTED",
        "RETURNED",
        "SUBMITTED",
    ]
    assert timeline[2]["remarks"] == "Add a phone number."


def test_return_requires_remarks(auth_client, coordinator):
    placement = SubmittedPlacementFactory()
    response = auth_client(coordinator).post(
        f"{PLACEMENTS}{placement.id}/return/", {}, format="json"
    )
    assert response.status_code == 400
    assert response.json()["code"] == "validation_error"


def test_lists_are_scoped_by_role(auth_client, coordinator):
    mine = ApprovedPlacementFactory()
    ApprovedPlacementFactory()

    def ids(user):
        return {row["id"] for row in auth_client(user).get(PLACEMENTS).json()["results"]}

    assert ids(mine.student) == {str(mine.id)}
    assert ids(mine.workplace_supervisor) == {str(mine.id)}
    assert ids(mine.academic_supervisor) == {str(mine.id)}
    assert len(ids(coordinator)) == 2


def test_coordinator_can_filter_by_supervisor_and_status(auth_client, coordinator):
    mine = ApprovedPlacementFactory()
    ApprovedPlacementFactory()
    response = auth_client(coordinator).get(
        PLACEMENTS, {"supervisor": str(mine.academic_supervisor_id), "status": "APPROVED"}
    )
    assert [row["id"] for row in response.json()["results"]] == [str(mine.id)]


