def test_organizations_flow(auth_client, student, coordinator):
    client = auth_client(student)
    created = client.post(
        "/api/v1/organizations/", {"name": "Startup Ltd", "county": "Nairobi"}, format="json"
    )
    assert created.status_code == 201, created.content
    assert created.json()["is_verified"] is False
    org_id = created.json()["id"]
    assert client.post(f"/api/v1/organizations/{org_id}/verify/").status_code == 403
    verified = auth_client(coordinator).post(f"/api/v1/organizations/{org_id}/verify/")
    assert verified.status_code == 200
    assert verified.json()["is_verified"] is True


def test_students_do_not_see_contact_details_of_other_organizations(auth_client, student):
    other = OrganizationFactory(is_verified=True, created_by=StudentFactory())
    response = auth_client(student).get(f"/api/v1/organizations/{other.id}/")
    assert response.status_code == 200
    assert "contact_email" not in response.json()
    assert response.json()["name"] == other.name


def test_periods_are_readable_by_all_but_writable_by_coordinators(
    auth_client, student, coordinator
):
    payload = {
        "name": "2027 Attachment",
        "type": "ATTACHMENT",
        "start_date": "2027-01-04",
        "end_date": "2027-04-30",
        "required_hours": 400,
        "min_visits": 2,
    }
    assert auth_client(student).post("/api/v1/periods/", payload, format="json").status_code == 403
    created = auth_client(coordinator).post("/api/v1/periods/", payload, format="json")
    assert created.status_code == 201, created.content
    assert auth_client(student).get("/api/v1/periods/").status_code == 200
    bad = auth_client(coordinator).post(
        "/api/v1/periods/", {**payload, "end_date": "2026-12-31"}, format="json"
    )
    assert bad.status_code == 400


def test_grade_bands_round_trip(auth_client, student, coordinator):
    period = PeriodFactory()
    url = f"/api/v1/periods/{period.id}/grade-bands/"
    bands = [{"min_percent": "70", "label": "A"}, {"min_percent": "0", "label": "F"}]
    assert auth_client(student).put(url, bands, format="json").status_code == 403
    assert auth_client(coordinator).put(url, bands, format="json").status_code == 200
    listed = auth_client(student).get(url).json()
    assert [band["label"] for band in listed] == ["A", "F"]
